package com.campusfest.backend.judging;
import com.campusfest.backend.competition.Competition; import com.campusfest.backend.entity.User; import com.campusfest.backend.registration.Registration; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="evaluations",uniqueConstraints=@UniqueConstraint(name="uk_evaluation_judge_registration",columnNames={"judge_id","registration_id"}),indexes={@Index(name="idx_eval_competition",columnList="competition_id"),@Index(name="idx_eval_registration",columnList="registration_id")})
public class Evaluation{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="competition_id",nullable=false) Competition competition; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="registration_id",nullable=false) Registration registration; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="judge_id",nullable=false) User judge; @Column(nullable=false) Integer totalScore; @Column(nullable=false,updatable=false) Instant submittedAt; @PrePersist void onCreate(){submittedAt=Instant.now();} public Long getId(){return id;} public Competition getCompetition(){return competition;} public void setCompetition(Competition v){competition=v;} public Registration getRegistration(){return registration;} public void setRegistration(Registration v){registration=v;} public User getJudge(){return judge;} public void setJudge(User v){judge=v;} public Integer getTotalScore(){return totalScore;} public void setTotalScore(Integer v){totalScore=v;} public Instant getSubmittedAt(){return submittedAt;}}
